37	RichKafkaProducer::RichKafkaProducer(Event::Dispatcher& dispatcher,
38	                                     Thread::ThreadFactory& thread_factory,
39	                                     const RawKafkaProducerConfig& configuration,
40	                                     const LibRdKafkaUtils& utils)
41	    : dispatcher_{dispatcher} {
42	
43	  // Create producer configuration object.
44	  std::unique_ptr<RdKafka::Conf> conf =
45	      std::unique_ptr<RdKafka::Conf>(RdKafka::Conf::create(RdKafka::Conf::CONF_GLOBAL));
46	  std::string errstr;
47	
48	  // Setup producer custom properties.
49	  for (const auto& e : configuration) {
50	    if (utils.setConfProperty(*conf, e.first, e.second, errstr) != RdKafka::Conf::CONF_OK) {
51	      throw EnvoyException(absl::StrCat("Could not set producer property [", e.first, "] to [",
52	                                        e.second, "]:", errstr));
53	    }
54	  }
55	
56	  // Setup callback (this callback is going to be invoked in dedicated monitoring thread).
57	  if (utils.setConfDeliveryCallback(*conf, this, errstr) != RdKafka::Conf::CONF_OK) {
58	    throw EnvoyException(absl::StrCat("Could not set producer callback:", errstr));
59	  }
60	
61	  // Finally, we create the producer.
62	  producer_ = utils.createProducer(conf.get(), errstr);
63	  if (!producer_) {
64	    throw EnvoyException(absl::StrCat("Could not create producer:", errstr));
65	  }
66	
67	  // Start the monitoring thread.
68	  poller_thread_active_ = true;
69	  std::function<void()> thread_routine = [this]() -> void { checkDeliveryReports(); };
70	  poller_thread_ = thread_factory.createThread(thread_routine);
71	}
